<script>
(() => { const total=document.getElementById('it-total'), discount=document.getElementById('it-discount'), rate=document.getElementById('it-rate'), months=document.getElementById('it-months'), first=document.getElementById('it-first'); if(!total)return; const render=()=>{const amount=Number(total.value||0),percent=Number(discount.selectedOptions[0].dataset.rate||0),discountAmount=Math.round(amount*percent)/100,base=Math.max(0,amount-discountAmount);const charge=Math.round(base*Number(rate.value||0))/100;const net=Math.round((base+charge)*100)/100;const n=Math.max(2,Number(months.value||2));const monthly=Math.round(net/n*100)/100;document.getElementById('it-summary').textContent=`Discounted balance ₱${base.toFixed(2)} · flat finance charge ₱${charge.toFixed(2)} · total cost ₱${net.toFixed(2)}`;let html='<table class="table table-sm"><thead><tr><th>Month</th><th>Due date</th><th>Amount</th></tr></thead><tbody>';let d=first.value?new Date(first.value+'T12:00:00'):null;for(let i=1;i<=n;i++){let a=i===n?Math.round((net-monthly*(n-1))*100)/100:monthly;let date='Set first due date';if(d){let y=d.getFullYear(),m=d.getMonth()+i-1,day=d.getDate(),last=new Date(y,m+1,0).getDate();date=new Date(y,m,Math.min(day,last)).toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'});}html+=`<tr><td>${i}</td><td>${date}</td><td>₱${a.toFixed(2)}</td></tr>`;}document.getElementById('it-preview').innerHTML=html+'</tbody></table>';};[total,discount,rate,months,first].forEach(x=>x.addEventListener('input',render));render(); })();
</script>
